          await showProjects();
        } catch (problem) {
          error.textContent = problem.message;
          error.hidden = false;
        }
      });
      app.querySelectorAll('[data-project-id]').forEach(button => button.addEventListener('click', () => {
        location.href = `/projects/${button.dataset.projectId}`;
      }));
    }

    async function showProject(id) {
      try {
        const project = await request(`/api/projects/${id}`);
        app.innerHTML = `<button class="back" type="button">Projects</button><h1>${escapeText(project.name)}</h1>`;
        app.querySelector('button').addEventListener('click', () => { location.href = '/'; });
      } catch {
        app.innerHTML = '<h1>Project not found</h1><button class="back" type="button">Projects</button>';
        app.querySelector('button').addEventListener('click', () => { location.href = '/'; });
      }
    }

    if (projectMatch) showProject(projectMatch[1]);
    else showProjects();
  </script>
</body>
</html>

